namespace ghidra.app.plugin.core.decompile.actions;



using docking.action;
using ghidra.app.decompiler;
using ghidra.app.decompiler.component;
using ghidra.app.decompiler.component;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.program.model.pcode;
using ghidra.program.model.pcode;
using ghidra.util;

public class ForwardSliceAction : AbstractDecompilerAction {

	public ForwardSliceAction() : base("Highlight Forward Slice")
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionHighlight"));
		setPopupMenuData(new MenuData(new string[] { "Highlight", "Forward Slice" }, "Decompile"));
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		ClangToken tokenAtCursor = context.getTokenAtCursor();
		Varnode varnode = DecompilerUtils.getVarnodeRef(tokenAtCursor);
		return varnode != null;
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		ClangToken tokenAtCursor = context.getTokenAtCursor();
		Varnode varnode = DecompilerUtils.getVarnodeRef(tokenAtCursor);
		if (varnode == null) {
			return;
		}

		PcodeOp op = tokenAtCursor.getPcodeOp();
		Set<Varnode> forwardSlice = DecompilerUtils.getForwardSlice(varnode);
		DecompilerPanel decompilerPanel = context.getDecompilerPanel();
		decompilerPanel.clearPrimaryHighlights();

		SliceHighlightColorProvider colorProvider =
			new SliceHighlightColorProvider(decompilerPanel, forwardSlice, varnode, op);
		decompilerPanel.addHighlights(forwardSlice, colorProvider);
	}

}
